def tar_bundle_files(file_set, output_path):
    tar = tarfile.open(output_path, "w")
    for f in file_set:
        tar.add(f)
    tar.close()

def extract_tar_bundle(file_set, output_path):
    tar = tarfile.open(file_set)
    tar.extractall(path=output_path+"/..")

def move_another_dir(files, source_dir, dest_dir):

    shutil.move(files, dest_dir)

    source_dir = os.scandir(source_dir)
    for entry in source_dir:
        if entry.is_file():
            extract_tar_bundle(entry.path, source_dir.parent.dir)
            move_another_dir(entry, entry.parent, source_dir.parent.parent)

