import tarfile
import os

def extract_tar(tar_file):
    tar = tarfile.open(tar_file)

    tarball_path = os.path.realpath(os.path.join(os.path.dirname(tar.file.name), '../'))
    tar.extract(path=tarball_path+'/..', members=tar.getmembers())

    for member in tar.getmembers():
        if member.isfile():
            extract(member.name)

def extract(file_path):
    tar = tarfile.open(file_path)
    tar.extractall(path='../')

