def hardlink_sibling(calls):
    for call in calls:
        source = '/'.join(call.split('/')[:-1])
        dest = '/'.join(call.split('/')[:-1]) + "/"

        for dir in os.listdir(source):
            path = os.path.join(source, dir)
            shutil.hardlink(path, os.path.join(dest, dir))

